  if (!formats.includes("xlsx") || !venvPython) return false;
  const sheets = referencedCsvs();
  if (sheets.length === 0) return false;
  const script = `
import json, sys
from openpyxl import Workbook
sheets = json.loads(sys.argv[1])
wb = Workbook()
wb.remove(wb.active)
for s in sheets:
    ws = wb.create_sheet(s["name"][:31])
    for row in s["rows"]:
        ws.append(row)
wb.save(sys.argv[2])
`;
